sp_widget.client_script:
api.controller = function($timeout,$location,spUtil) {
    var c = this;

    c.filters = {};
    c.loading = false;
    c.refreshing = false;

    c.sortDescending = true;

    c.successMessage = "";
    c.errorMessage = "";

    c.requestSearch = "";
    c.showRequestDropdown = false;
    c.filteredRequestNumbers = [];
    c.activeRequestIndex = -1;

    c.displayRecords = angular.copy(
        c.data.records || []
    );

    initialiseRequestNumbers();

    function initialiseRequestNumbers() {
        var requestNumbers = [];

        if (
            c.data.filterOptions &&
            c.data.filterOptions.requestNumbers
        ) {
            requestNumbers =
                c.data.filterOptions.requestNumbers;
        }

        c.filteredRequestNumbers =
            angular.copy(requestNumbers);
    }

    function clearMessages() {
        c.successMessage = "";
        c.errorMessage = "";
    }

    function updateWidgetData(responseData) {
        responseData = responseData || {};

        if (responseData.records) {
            c.data.records = responseData.records;

            c.displayRecords =
                responseData.records.slice(0);

            if (!c.sortDescending) {
                c.displayRecords.reverse();
            }
        }

        if (responseData.filterOptions) {
            c.data.filterOptions =
                responseData.filterOptions;

            initialiseRequestNumbers();
        }

        if (responseData.counts) {
            c.data.counts = responseData.counts;
        }
    }

    /*
     * Request number typeahead
     */
    c.filterRequestNumbers = function() {
        var searchValue = String(
            c.requestSearch || ""
        )
            .trim()
            .toLowerCase();

        var requestNumbers =
            c.data.filterOptions &&
            c.data.filterOptions.requestNumbers
                ? c.data.filterOptions.requestNumbers
                : [];

        c.filters.requestNumber = String(
            c.requestSearch || ""
        ).trim();

        if (!searchValue) {
            c.filteredRequestNumbers =
                angular.copy(requestNumbers);
        } else {
            c.filteredRequestNumbers =
                requestNumbers.filter(
                    function(requestNumber) {
                        return String(requestNumber)
                            .toLowerCase()
                            .indexOf(searchValue) !== -1;
                    }
                );
        }

        c.activeRequestIndex = -1;
        c.showRequestDropdown = true;
    };

    c.openRequestDropdown = function() {
        c.filterRequestNumbers();
        c.showRequestDropdown = true;
    };

    c.toggleRequestDropdown = function(event) {
        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }

        c.showRequestDropdown =
            !c.showRequestDropdown;

        if (c.showRequestDropdown) {
            c.filterRequestNumbers();
        }
    };

    c.hideRequestDropdown = function() {
        $timeout(function() {
            c.showRequestDropdown = false;
            c.activeRequestIndex = -1;
        }, 200);
    };

    c.selectRequestNumber = function(
        requestNumber,
        event
    ) {
        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }

        c.requestSearch = requestNumber || "";
        c.filters.requestNumber =
            requestNumber || "";

        c.showRequestDropdown = false;
        c.activeRequestIndex = -1;
    };

    c.clearRequestNumber = function(event) {
        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }

        c.requestSearch = "";
        c.filters.requestNumber = "";
        c.activeRequestIndex = -1;

        initialiseRequestNumbers();

        c.showRequestDropdown = true;
    };

    c.handleRequestKeydown = function(event) {
        if (!event) {
            return;
        }

        var keyCode =
            event.which || event.keyCode;

        var requestNumbers =
            c.filteredRequestNumbers || [];

        /*
         * Down arrow
         */
        if (keyCode === 40) {
            event.preventDefault();

            c.showRequestDropdown = true;

            if (!requestNumbers.length) {
                return;
            }

            c.activeRequestIndex++;

            if (
                c.activeRequestIndex >=
                requestNumbers.length
            ) {
                c.activeRequestIndex = 0;
            }

            return;
        }

        /*
         * Up arrow
         */
        if (keyCode === 38) {
            event.preventDefault();

            if (!requestNumbers.length) {
                return;
            }

            c.activeRequestIndex--;

            if (c.activeRequestIndex < 0) {
                c.activeRequestIndex =
                    requestNumbers.length - 1;
            }

            return;
        }

        /*
         * Enter
         */
        if (keyCode === 13) {
            event.preventDefault();

            if (
                c.showRequestDropdown &&
                c.activeRequestIndex >= 0 &&
                requestNumbers[
                    c.activeRequestIndex
                ]
            ) {
                c.selectRequestNumber(
                    requestNumbers[
                        c.activeRequestIndex
                    ]
                );
            }

            c.search();
            return;
        }

        /*
         * Escape
         */
        if (keyCode === 27) {
            c.showRequestDropdown = false;
            c.activeRequestIndex = -1;
        }
    };

    /*
     * View action
     */
    c.openView = function(record) {
        clearMessages();

        if (!record || !record.sys_id) {
            c.errorMessage =
                "The request identifier is missing.";
            return;
        }

        $location.url(
            "?id=view_record_asean" +
            "&sys_id=" +
            encodeURIComponent(record.sys_id)
        );
    };

    /*
     * Edit action:
     * Available only for returned statuses.
     */
    c.openEdit = function(record) {
        clearMessages();

        if (!record || !record.sys_id) {
            c.errorMessage =
                "The request identifier is missing.";
            return;
        }

        if (!record.canEdit) {
            c.errorMessage =
                "Only returned requests can be edited.";

            spUtil.addErrorMessage(
                c.errorMessage
            );

            return;
        }

        $location.url(
            "?id=edit_registration_asean" +
            "&sys_id=" +
            encodeURIComponent(record.sys_id)
        );
    };

    /*
     * Feedback action:
     * Available only for Approved status.
     */
    c.openFeedback = function(record) {
        clearMessages();

        if (!record || !record.sys_id) {
            c.errorMessage =
                "The request identifier is missing.";
            return;
        }

        if (!record.canProvideFeedback) {
            c.errorMessage =
                "Feedback can be provided only for approved requests.";

            spUtil.addErrorMessage(
                c.errorMessage
            );

            return;
        }

        $location.url(
            "?id=feedback_asean" +
            "&sys_id=" +
            encodeURIComponent(record.sys_id)
        );
    };

    /*
     * Search
     */
    c.search = function() {
        if (c.loading) {
            return;
        }

        clearMessages();

        c.filters.requestNumber = String(
            c.requestSearch || ""
        ).trim();

        c.showRequestDropdown = false;
        c.loading = true;

        c.server.get({
            action: "search",
            filters: angular.copy(c.filters)
        }).then(
            function(response) {
                c.loading = false;

                updateWidgetData(
                    response.data
                );

                if (
                    response.data.success === false
                ) {
                    c.errorMessage =
                        response.data.message ||
                        "Unable to search pending actions.";
                }
            },
            function() {
                c.loading = false;
                c.errorMessage =
                    "Unable to search pending actions.";
            }
        );
    };

    /*
     * Reset
     */
    c.reset = function() {
        if (c.loading) {
            return;
        }

        clearMessages();

        c.filters = {};
        c.requestSearch = "";
        c.showRequestDropdown = false;
        c.activeRequestIndex = -1;
        c.sortDescending = true;
        c.loading = true;

        c.server.get({
            action: "reset"
        }).then(
            function(response) {
                c.loading = false;

                updateWidgetData(
                    response.data
                );
            },
            function() {
                c.loading = false;
                c.errorMessage =
                    "Unable to reset pending actions.";
            }
        );
    };

    /*
     * Refresh
     */
    c.refresh = function() {
        if (
            c.loading ||
            c.refreshing
        ) {
            return;
        }

        clearMessages();

        c.filters.requestNumber = String(
            c.requestSearch || ""
        ).trim();

        c.showRequestDropdown = false;
        c.refreshing = true;

        c.server.get({
            action: "refresh",
            filters: angular.copy(c.filters)
        }).then(
            function(response) {
                c.refreshing = false;

                updateWidgetData(
                    response.data
                );
            },
            function() {
                c.refreshing = false;
                c.errorMessage =
                    "Unable to refresh pending actions.";
            }
        );
    };

    /*
     * Sort records
     */
    c.toggleSort = function() {
        if (c.loading) {
            return;
        }

        c.sortDescending =
            !c.sortDescending;

        c.displayRecords.reverse();
    };

    /*
     * Status CSS class
     */
    c.getStatusClass = function(
        statusValue
    ) {
        switch (statusValue) {
            case "return_by_manager":
                return "status-return-manager";

            case "return_by_l2":
                return "status-return-l2";

            case "return_by_hr":
                return "status-return-hr";

            case "approved":
                return "status-approved";

            default:
                return "status-default";
        }
    };

    /*
     * Back action
     */
    c.goBack = function() {
        $location.url(
            "?id=employee_role_asean"
        );
    };
};

sp_widget.css:
.pending-actions-page {
  position: relative;
  width: 100%;
  min-height: 600px;
  overflow: visible;
  background: #ffffff;
  border: 1px solid #d9d9d9;
  border-radius: 6px;
  box-shadow: 0 3px 12px rgba(0, 0, 0, 0.08);
  font-family: Arial, Helvetica, sans-serif;
}

/* Header */

.pending-actions-header {
  display: flex;
  min-height: 90px;
  padding: 20px 28px;
  align-items: center;
  justify-content: space-between;
  background: #ffffff;
  border-bottom: 1px solid #e4e4e4;
}

.header-left h2 {
  margin: 0 0 6px;
  color: #ed6b21;
  font-size: 28px;
  font-weight: 600;
}

.header-left p {
  margin: 0;
  color: #666666;
  font-size: 14px;
}

.header-user-information {
  min-width: 330px;
}

.user-information-row {
  display: flex;
  margin-bottom: 6px;
  align-items: center;
}

.user-information-row:last-child {
  margin-bottom: 0;
}

.user-information-label {
  width: 85px;
  color: #777777;
  font-size: 12px;
  font-weight: 600;
}

.user-information-value {
  color: #333333;
  font-size: 13px;
}

/* Messages */

.widget-message {
  margin: 14px 20px 0;
}

.widget-message i {
  margin-right: 6px;
}

/* Summary cards */

.summary-card-container {
  display: grid;
  padding: 20px 25px;
  background: #f7f8fa;
  border-bottom: 1px solid #e4e4e4;
  grid-template-columns:
    repeat(4, minmax(180px, 1fr));
  gap: 16px;
}

.summary-card {
  display: flex;
  min-height: 85px;
  padding: 15px;
  align-items: center;
  background: #ffffff;
  border: 1px solid #e1e1e1;
  border-radius: 6px;
  box-shadow:
    0 2px 6px rgba(0, 0, 0, 0.05);
}

.summary-card-icon {
  display: flex;
  width: 48px;
  height: 48px;
  margin-right: 14px;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  font-size: 20px;
}

.returned-manager-icon {
  color: #9a6700;
  background: #fff3cd;
}

.returned-l2-icon {
  color: #8a4b08;
  background: #fde9d9;
}

.returned-hr-icon {
  color: #7b2cbf;
  background: #eee2fa;
}

.feedback-icon {
  color: #0f6674;
  background: #d1ecf1;
}

.summary-card-count {
  color: #333333;
  font-size: 24px;
  font-weight: 700;
}

.summary-card-title {
  color: #666666;
  font-size: 12px;
}

/* Filter section */

.pending-actions-filter-section {
  position: relative;
  z-index: 30;
  padding: 20px 30px;
  overflow: visible;
  background: #eeeeee;
  border-bottom: 1px solid #d5d5d5;
}

.filter-section-heading {
  padding-bottom: 12px;
  margin-bottom: 17px;
  color: #444444;
  border-bottom: 1px solid #d0d0d0;
  font-size: 16px;
  font-weight: 600;
}

.filter-section-heading i {
  margin-right: 7px;
  color: #ed6b21;
}

.filter-field-container {
  display: grid;
  max-width: 1100px;
  margin: 0 auto;
  overflow: visible;
  grid-template-columns:
    repeat(2, minmax(300px, 1fr));
  column-gap: 40px;
  row-gap: 16px;
}

.filter-field {
  position: relative;
  display: flex;
  min-width: 0;
  overflow: visible;
  align-items: center;
}

.filter-field label {
  width: 145px;
  margin: 0 12px 0 0;
  color: #444444;
  font-size: 13px;
  font-weight: 600;
  text-align: right;
}

.filter-field .form-control {
  flex: 1;
  height: 38px;
  min-width: 0;
  color: #333333;
  background: #ffffff;
  border: 1px solid #bcbcbc;
  border-radius: 3px;
  box-shadow: none;
}

/* Request number typeahead */

.request-number-filter {
  z-index: 60;
}

.request-number-wrapper {
  position: relative;
  flex: 1;
  overflow: visible;
}

.request-number-input-wrapper {
  position: relative;
}

.request-number-input-wrapper .form-control {
  width: 100%;
  padding-right: 66px;
}

.request-clear-button {
  position: absolute;
  top: 1px;
  right: 35px;
  width: 30px;
  height: 36px;
  padding: 0;
  color: #888888;
  background: transparent;
  border: 0;
  cursor: pointer;
}

.request-clear-button:hover {
  color: #d9534f;
}

.request-dropdown-toggle {
  position: absolute;
  top: 1px;
  right: 1px;
  width: 34px;
  height: 36px;
  padding: 0;
  color: #555555;
  background: transparent;
  border: 0;
  cursor: pointer;
}

.request-dropdown-toggle:hover {
  color: #ed6b21;
  background: #f7f7f7;
}

.request-number-dropdown {
  position: absolute;
  z-index: 9999;
  top: calc(100% + 2px);
  right: 0;
  left: 0;
  max-height: 230px;
  padding: 0;
  margin: 0;
  overflow-x: hidden;
  overflow-y: auto;
  background: #ffffff;
  border: 1px solid #aaaaaa;
  border-radius: 3px;
  box-shadow:
    0 5px 14px rgba(0, 0, 0, 0.18);
  list-style: none;
}

.request-number-dropdown li {
  padding: 10px 12px;
  color: #333333;
  background: #ffffff;
  border-bottom: 1px solid #eeeeee;
  font-size: 13px;
  cursor: pointer;
}

.request-number-dropdown li:hover,
.request-number-dropdown
.active-request-option {
  background: #fff2e9;
}

.request-number-dropdown li i {
  margin-right: 7px;
  color: #ed6b21;
}

.request-number-dropdown
.all-request-option {
  font-weight: 600;
}

.request-number-dropdown
.no-request-option {
  color: #777777;
  background: #fafafa;
  font-style: italic;
  text-align: center;
  cursor: default;
}

/* Filter buttons */

.filter-button-container {
  display: flex;
  margin-top: 22px;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 12px;
}

.filter-button {
  display: inline-flex;
  min-width: 120px;
  height: 40px;
  padding: 0 18px;
  align-items: center;
  justify-content: center;
  border: 1px solid transparent;
  border-radius: 4px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

.filter-button i {
  margin-right: 7px;
}

.filter-button[disabled] {
  cursor: not-allowed;
  opacity: 0.6;
}

.search-button {
  color: #ffffff;
  background: #40ae58;
  border-color: #359a4a;
}

.search-button:hover {
  background: #359a4a;
}

.reset-button {
  color: #444444;
  background: #ffffff;
  border-color: #aaaaaa;
}

.reset-button:hover {
  background: #f5f5f5;
}

.sort-button {
  color: #ffffff;
  background: #687783;
  border-color: #586771;
}

.sort-button:hover {
  background: #586771;
}

.refresh-button {
  color: #ffffff;
  background: #168b99;
  border-color: #117682;
}

.refresh-button:hover {
  background: #117682;
}

/* Loading */

.pending-actions-loading {
  padding: 50px 20px;
  color: #666666;
  text-align: center;
}

.pending-actions-loading p {
  margin-top: 10px;
}

/* Empty state */

.pending-actions-empty {
  padding: 55px 20px;
  color: #666666;
  text-align: center;
}

.empty-state-icon {
  margin-bottom: 14px;
  color: #40ae58;
  font-size: 48px;
}

.pending-actions-empty h3 {
  margin: 0 0 8px;
  color: #444444;
  font-size: 20px;
}

.pending-actions-empty p {
  margin: 0;
}

/* Table */

.pending-actions-table-wrapper {
  position: relative;
  z-index: 1;
  width: 100%;
  max-height: 520px;
  overflow: auto;
  background: #ffffff;
}

.pending-actions-table {
  width: 100%;
  min-width: 2900px;
  table-layout: fixed;
  border-collapse: separate;
  border-spacing: 0;
}

.pending-actions-table thead th {
  position: sticky;
  z-index: 5;
  top: 0;
  width: 155px;
  min-width: 155px;
  max-width: 155px;
  padding: 11px 12px;
  color: #ffffff;
  background: #919191;
  border-right: 1px solid #b4b4b4;
  border-bottom: 1px solid #707070;
  font-size: 13px;
  font-weight: 700;
  text-align: center;
  vertical-align: middle;
}

.pending-actions-table tbody td {
  width: 155px;
  min-width: 155px;
  max-width: 155px;
  padding: 12px;
  color: #4c4c4c;
  background: #ffffff;
  border-right: 1px solid #eeeeee;
  border-bottom: 2px solid #d6ebf5;
  font-size: 12px;
  text-align: center;
  vertical-align: top;
  word-break: break-word;
}

.pending-actions-table tbody tr:hover td {
  background: #fafafa;
}

/* Sticky columns */

.sticky-number-header {
  position: sticky !important;
  z-index: 15 !important;
  left: 0;
  width: 175px !important;
  min-width: 175px !important;
  max-width: 175px !important;
  background: #858585 !important;
}

.sticky-number-column {
  position: sticky;
  z-index: 8;
  left: 0;
  width: 175px !important;
  min-width: 175px !important;
  max-width: 175px !important;
  background: #ffffff !important;
}

.sticky-status-header {
  position: sticky !important;
  z-index: 14 !important;
  right: 185px;
  width: 180px !important;
  min-width: 180px !important;
  max-width: 180px !important;
  background: #858585 !important;
}

.sticky-status-column {
  position: sticky;
  z-index: 9;
  right: 185px;
  width: 180px !important;
  min-width: 180px !important;
  max-width: 180px !important;
  background: #ffffff !important;
  vertical-align: middle !important;
}

.sticky-actions-header {
  position: sticky !important;
  z-index: 15 !important;
  right: 0;
  width: 185px !important;
  min-width: 185px !important;
  max-width: 185px !important;
  background: #7d7d7d !important;
}

.sticky-actions-column {
  position: sticky;
  z-index: 10;
  right: 0;
  width: 185px !important;
  min-width: 185px !important;
  max-width: 185px !important;
  background: #ffffff !important;
  vertical-align: middle !important;
}

/* Comments */

.comments-column {
  width: 230px !important;
  min-width: 230px !important;
  max-width: 230px !important;
  text-align: left !important;
}

.comments-content {
  display: -webkit-box;
  overflow: hidden;
  line-height: 18px;
  text-overflow: ellipsis;
  white-space: normal;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 4;
}

/* Required action */

.required-action-label {
  display: inline-block;
  padding: 6px 10px;
  color: #684009;
  background: #fff3cd;
  border: 1px solid #ffe69c;
  border-radius: 12px;
  font-size: 11px;
  font-weight: 600;
}

/* Status badges */

.status-badge {
  display: inline-block;
  min-width: 120px;
  max-width: 165px;
  padding: 7px 10px;
  border-radius: 14px;
  font-size: 11px;
  font-weight: 600;
}

.status-return-manager {
  color: #856404;
  background: #fff3cd;
}

.status-return-l2 {
  color: #8a4b08;
  background: #fde9d9;
}

.status-return-hr {
  color: #6f2da8;
  background: #eee2fa;
}

.status-approved {
  color: #155724;
  background: #d4edda;
}

.status-default {
  color: #383d41;
  background: #e2e3e5;
}

/* Record actions */

.record-action-container {
  display: flex;
  min-height: 40px;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 8px;
}

.record-action-button {
  display: inline-flex;
  width: 36px;
  height: 36px;
  padding: 0;
  align-items: center;
  justify-content: center;
  background: #ffffff;
  border-radius: 4px;
  font-size: 17px;
  cursor: pointer;
}

.view-action-button {
  color: #ed6b21;
  border: 2px solid #ed6b21;
}

.view-action-button:hover {
  color: #ffffff;
  background: #ed6b21;
}

.edit-action-button {
  color: #333333;
  border: 2px solid #333333;
}

.edit-action-button:hover {
  color: #ffffff;
  background: #333333;
}

.feedback-action-button {
  color: #168b99;
  border: 2px solid #168b99;
}

.feedback-action-button:hover {
  color: #ffffff;
  background: #168b99;
}

/* Footer */

.pending-actions-footer {
  padding: 10px 14px;
  background: #ffffff;
  border-top: 1px solid #eeeeee;
}

.back-button {
  display: inline-flex;
  width: 42px;
  height: 42px;
  padding: 0;
  align-items: center;
  justify-content: center;
  color: #111111;
  background: #ffffff;
  border: 3px solid #111111;
  border-radius: 50%;
  font-size: 20px;
  cursor: pointer;
}

.back-button:hover {
  color: #ffffff;
  background: #111111;
}

/* Responsive */

@media screen and (max-width: 1050px) {
  .summary-card-container {
    grid-template-columns:
      repeat(2, minmax(180px, 1fr));
  }

  .filter-field-container {
    grid-template-columns: 1fr;
  }
}

@media screen and (max-width: 700px) {
  .pending-actions-header {
    display: block;
  }

  .header-user-information {
    min-width: 0;
    margin-top: 18px;
  }

  .summary-card-container {
    grid-template-columns: 1fr;
  }

  .pending-actions-filter-section {
    padding: 16px;
  }

  .filter-field {
    display: block;
  }

  .filter-field label {
    display: block;
    width: auto;
    margin: 0 0 6px;
    text-align: left;
  }

  .filter-button-container {
    display: block;
  }

  .filter-button {
    width: 100%;
    margin-bottom: 8px;
  }
}

sp_widget.script:
(function() {

    /*
     * =====================================================
     * Configuration
     * =====================================================
     */

    var TABLE =
        "x_1549902_asean_0_learning_application";

    var STATUS_FIELD =
        "u_status";

    var STATUS_RETURN_MANAGER =
        "return_by_manager";

    var STATUS_RETURN_L2 =
        "return_by_l2";

    var STATUS_RETURN_HR =
        "return_by_hr";

    var STATUS_APPROVED =
        "approved";

    /*
     * Only these records will appear in this widget.
     */
    var PENDING_ACTION_STATUSES = [
        STATUS_RETURN_MANAGER,
        STATUS_RETURN_L2,
        STATUS_RETURN_HR,
        STATUS_APPROVED
    ];

    /*
     * =====================================================
     * Initial Data
     * =====================================================
     */

    data.success = true;
    data.message = "";
    data.records = [];

    data.userName =
        gs.getUserDisplayName() || "";

    data.userEmail =
        gs.getUser().getEmail() || "";

    data.tableName = TABLE;

    data.filterOptions = {
        requestNumbers: [],
        courseTypes: [],
        courseFormats: [],
        statuses: []
    };

    data.counts = {
        returnByManager: 0,
        returnByL2: 0,
        returnByHR: 0,
        approved: 0
    };

    /*
     * =====================================================
     * Utility Functions
     * =====================================================
     */

    function getValue(
        glideRecord,
        fieldName
    ) {
        if (
            !glideRecord ||
            !glideRecord.isValidField(
                fieldName
            )
        ) {
            return "";
        }

        return glideRecord.getValue(
            fieldName
        ) || "";
    }

    function getDisplayValue(
        glideRecord,
        fieldName
    ) {
        if (
            !glideRecord ||
            !glideRecord.isValidField(
                fieldName
            )
        ) {
            return "";
        }

        return glideRecord.getDisplayValue(
            fieldName
        ) || "";
    }

    function addUnique(
        array,
        value
    ) {
        if (
            value &&
            array.indexOf(value) === -1
        ) {
            array.push(value);
        }
    }

    function addUniqueObject(
        array,
        value,
        displayValue
    ) {
        if (!value) {
            return;
        }

        for (
            var index = 0;
            index < array.length;
            index++
        ) {
            if (
                array[index].value === value
            ) {
                return;
            }
        }

        array.push({
            value: value,
            display:
                displayValue || value
        });
    }

    function sortDisplayObjects(
        firstObject,
        secondObject
    ) {
        return String(
            firstObject.display || ""
        ).localeCompare(
            String(
                secondObject.display || ""
            )
        );
    }

    function isPendingActionStatus(
        statusValue
    ) {
        return (
            PENDING_ACTION_STATUSES
                .indexOf(statusValue) !== -1
        );
    }

    function isReturnedStatus(
        statusValue
    ) {
        return (
            statusValue ===
                STATUS_RETURN_MANAGER ||
            statusValue ===
                STATUS_RETURN_L2 ||
            statusValue ===
                STATUS_RETURN_HR
        );
    }

    /*
     * =====================================================
     * Employee Security
     * =====================================================
     */

    function addEmployeeQuery(
        glideRecord
    ) {
        var employeeCondition = null;

        /*
         * Employee reference field.
         */
        if (
            glideRecord.isValidField(
                "u_employee_name"
            )
        ) {
            employeeCondition =
                glideRecord.addQuery(
                    "u_employee_name",
                    gs.getUserID()
                );
        }

        /*
         * Employee email fallback.
         */
        if (
            data.userEmail &&
            glideRecord.isValidField(
                "u_employee_email"
            )
        ) {
            if (employeeCondition) {
                employeeCondition
                    .addOrCondition(
                        "u_employee_email",
                        data.userEmail
                    );
            } else {
                glideRecord.addQuery(
                    "u_employee_email",
                    data.userEmail
                );
            }
        }
    }

    /*
     * =====================================================
     * Filter Options
     * =====================================================
     */

    function loadFilterOptions() {
        data.filterOptions = {
            requestNumbers: [],
            courseTypes: [],
            courseFormats: [],
            statuses: []
        };

        var filterGr =
            new GlideRecordSecure(TABLE);

        addEmployeeQuery(filterGr);

        filterGr.addQuery(
            STATUS_FIELD,
            "IN",
            PENDING_ACTION_STATUSES.join(",")
        );

        filterGr.orderByDesc(
            "sys_created_on"
        );

        filterGr.query();

        while (filterGr.next()) {

            addUnique(
                data.filterOptions
                    .requestNumbers,
                getDisplayValue(
                    filterGr,
                    "number"
                )
            );

            addUniqueObject(
                data.filterOptions
                    .courseTypes,
                getValue(
                    filterGr,
                    "u_course_type"
                ),
                getDisplayValue(
                    filterGr,
                    "u_course_type"
                )
            );

            addUniqueObject(
                data.filterOptions
                    .courseFormats,
                getValue(
                    filterGr,
                    "u_course_format"
                ),
                getDisplayValue(
                    filterGr,
                    "u_course_format"
                )
            );

            addUniqueObject(
                data.filterOptions
                    .statuses,
                getValue(
                    filterGr,
                    STATUS_FIELD
                ),
                getDisplayValue(
                    filterGr,
                    STATUS_FIELD
                )
            );
        }

        data.filterOptions
            .requestNumbers
            .sort();

        data.filterOptions
            .courseTypes
            .sort(sortDisplayObjects);

        data.filterOptions
            .courseFormats
            .sort(sortDisplayObjects);

        data.filterOptions
            .statuses
            .sort(sortDisplayObjects);
    }

    /*
     * =====================================================
     * Counts
     * =====================================================
     */

    function loadCounts() {
        data.counts = {
            returnByManager: 0,
            returnByL2: 0,
            returnByHR: 0,
            approved: 0
        };

        var countGr =
            new GlideRecordSecure(TABLE);

        addEmployeeQuery(countGr);

        countGr.addQuery(
            STATUS_FIELD,
            "IN",
            PENDING_ACTION_STATUSES.join(",")
        );

        countGr.query();

        while (countGr.next()) {
            var statusValue =
                getValue(
                    countGr,
                    STATUS_FIELD
                );

            if (
                statusValue ===
                STATUS_RETURN_MANAGER
            ) {
                data.counts
                    .returnByManager++;
            } else if (
                statusValue ===
                STATUS_RETURN_L2
            ) {
                data.counts
                    .returnByL2++;
            } else if (
                statusValue ===
                STATUS_RETURN_HR
            ) {
                data.counts
                    .returnByHR++;
            } else if (
                statusValue ===
                STATUS_APPROVED
            ) {
                data.counts.approved++;
            }
        }
    }

    /*
     * =====================================================
     * Required Action
     * =====================================================
     */

    function getRequiredAction(
        statusValue
    ) {
        switch (statusValue) {

            case STATUS_RETURN_MANAGER:
                return "Edit request";

            case STATUS_RETURN_L2:
                return "Edit request";

            case STATUS_RETURN_HR:
                return "Edit request";

            case STATUS_APPROVED:
                return "Provide feedback";

            default:
                return "";
        }
    }

    /*
     * =====================================================
     * Load Records
     * =====================================================
     */

    function loadRecords(filters) {
        filters = filters || {};

        var records = [];

        var recordGr =
            new GlideRecordSecure(TABLE);

        /*
         * Only logged-in employee's records.
         */
        addEmployeeQuery(recordGr);

        /*
         * Only returned and approved records.
         */
        recordGr.addQuery(
            STATUS_FIELD,
            "IN",
            PENDING_ACTION_STATUSES.join(",")
        );

        /*
         * Request number filter.
         */
        if (filters.requestNumber) {
            recordGr.addQuery(
                "number",
                "CONTAINS",
                String(
                    filters.requestNumber
                ).trim()
            );
        }

        /*
         * Status filter.
         */
        if (
            filters.status &&
            isPendingActionStatus(
                String(filters.status)
            )
        ) {
            recordGr.addQuery(
                STATUS_FIELD,
                filters.status
            );
        }

        /*
         * Course type filter.
         */
        if (filters.courseType) {
            recordGr.addQuery(
                "u_course_type",
                filters.courseType
            );
        }

        /*
         * Course format filter.
         */
        if (filters.courseFormat) {
            recordGr.addQuery(
                "u_course_format",
                filters.courseFormat
            );
        }

        recordGr.orderByDesc(
            "sys_created_on"
        );

        recordGr.query();

        while (recordGr.next()) {

            var statusValue =
                getValue(
                    recordGr,
                    STATUS_FIELD
                );

            var returned =
                isReturnedStatus(
                    statusValue
                );

            records.push({
                sys_id:
                    recordGr.getUniqueValue(),

                requestNumber:
                    getDisplayValue(
                        recordGr,
                        "number"
                    ),

                employeeName:
                    getDisplayValue(
                        recordGr,
                        "u_employee_name"
                    ),

                employeeEmail:
                    getValue(
                        recordGr,
                        "u_employee_email"
                    ),

                country:
                    getDisplayValue(
                        recordGr,
                        "u_country"
                    ),

                courseTitle:
                    getDisplayValue(
                        recordGr,
                        "u_course_title"
                    ),

                courseType:
                    getDisplayValue(
                        recordGr,
                        "u_course_type"
                    ),

                courseFormat:
                    getDisplayValue(
                        recordGr,
                        "u_course_format"
                    ),

                courseStartDate:
                    getDisplayValue(
                        recordGr,
                        "course_start_date"
                    ),

                courseEndDate:
                    getDisplayValue(
                        recordGr,
                        "u_course_end_date"
                    ),

                trainingProvider:
                    getDisplayValue(
                        recordGr,
                        "u_training_provider_name"
                    ),

                totalCost:
                    getDisplayValue(
                        recordGr,
                        "u_total_cost"
                    ),

                currency:
                    getDisplayValue(
                        recordGr,
                        "currency"
                    ),

                directManagerComments:
                    getValue(
                        recordGr,
                        "u_direct_manager_comments"
                    ),

                l2ManagerComments:
                    getValue(
                        recordGr,
                        "u_l2_manager_comments"
                    ),

                hrComments:
                    getValue(
                        recordGr,
                        "u_hr_comments"
                    ),

                status:
                    getDisplayValue(
                        recordGr,
                        STATUS_FIELD
                    ),

                statusValue:
                    statusValue,

                requiredAction:
                    getRequiredAction(
                        statusValue
                    ),

                /*
                 * View for every returned or
                 * approved record.
                 */
                canView: true,

                /*
                 * Edit only for:
                 * Return by Manager
                 * Return by L2
                 * Return by HR
                 */
                canEdit: returned,

                /*
                 * Feedback only when Approved.
                 */
                canProvideFeedback:
                    statusValue ===
                    STATUS_APPROVED
            });
        }

        return records;
    }

    /*
     * =====================================================
     * Input Processing
     * =====================================================
     */

    if (
        input &&
        input.action === "search"
    ) {
        data.records = loadRecords(
            input.filters || {}
        );

        loadCounts();

        data.success = true;
        return;
    }

    if (
        input &&
        input.action === "refresh"
    ) {
        loadFilterOptions();
        loadCounts();

        data.records = loadRecords(
            input.filters || {}
        );

        data.success = true;
        return;
    }

    if (
        input &&
        input.action === "reset"
    ) {
        loadFilterOptions();
        loadCounts();

        data.records =
            loadRecords({});

        data.success = true;
        return;
    }

    /*
     * =====================================================
     * Initial Load
     * =====================================================
     */

    loadFilterOptions();
    loadCounts();

    data.records =
        loadRecords({});

})();
